    `Key14` TINYINT UNSIGNED NOT NULL,
    `Key15` TINYINT UNSIGNED NOT NULL,
    `Key16` TINYINT UNSIGNED NOT NULL,
    `VerifiedBuild` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`ID`,`VerifiedBuild`) USING BTREE,
    INDEX `idx_tact_key_verified_build` (`VerifiedBuild`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


